<script setup lang="ts">import {onMounted,ref} from 'vue';const rows=ref<any[]>([]),editing=ref<any>(null),error=ref(''),loading=ref(false);const blank=()=>({companyName:'',taxNumber:'',billingAddress:'',contactName:'',email:'',password:'',pricingType:'FIXED',pricingValue:1000}),form=ref(blank()),h=()=>({Authorization:`Bearer ${localStorage.getItem('token')}`,'Content-Type':'application/json'});const load=async()=>{const r=await fetch('/api/admin/accounts',{headers:h()});if(r.ok)rows.value=await r.json()};onMounted(load);function edit(x:any){editing.value=x;form.value={...x,password:''}}function reset(){editing.value=null;form.value=blank();error.value=''}async function save(){const isEdit=!!editing.value?.id;if((!isEdit&&!form.value.password)||(form.value.password&&form.value.password.length<6)){error.value='A jelszónak legalább 6 karakterből kell állnia.';return}loading.value=true;error.value='';try{const r=await fetch(isEdit?`/api/admin/accounts/${editing.value.id}`:'/api/admin/accounts',{method:isEdit?'PUT':'POST',headers:h(),body:JSON.stringify(form.value)});if(!r.ok){error.value=(await r.json()).message||'Mentési hiba';return}reset();load()}catch{error.value='A szolgáltatás nem érhető el'}finally{loading.value=false}}async function toggle(x:any){await fetch(`/api/admin/accounts/${x.id}/active?value=${!x.active}`,{method:'PATCH',headers:h()});load()}</script>
<template><section class="card"><div class="card-head"><h1>Ügyfelek</h1><button @click="editing?reset():editing={}">+ Új ügyfél</button></div><form v-if="editing!==null" novalidate class="admin-form" @submit.prevent="save"><input v-model="form.companyName" required placeholder="Cégnév"><input v-model="form.taxNumber" placeholder="Adószám"><input v-model="form.billingAddress" placeholder="Számlázási cím"><input v-model="form.contactName" required placeholder="Kapcsolattartó"><input v-model="form.email" required type="email" placeholder="E-mail"><input v-model="form.password" :required="!editing?.id" type="password" :placeholder="editing?.id ? 'Jelszó — Hagyd üresen, ha nem szeretnéd módosítani.' : 'Jelszó (min. 6 karakter)'"><select v-model="form.pricingType"><option value="PERCENTAGE">Százalékos felár</option><option value="FIXED">Fix felár</option></select><input v-model.number="form.pricingValue" required type="number" min="0" step="0.01" placeholder="Felár"><p v-if="error" class="error">{{error}}</p><button :disabled="loading">Mentés</button><button type="button" class="secondary" @click="reset">Mégse</button></form><table><thead><tr><th>Cég</th><th>Adószám</th><th>Kapcsolattartó</th><th>E-mail</th><th>Árazás</th><th>Állapot</th><th></th></tr></thead><tbody><tr v-for="x in rows" :key="x.id"><td>{{x.companyName}}</td><td>{{x.taxNumber||'—'}}</td><td>{{x.contactName}}</td><td>{{x.email}}</td><td>{{x.pricingType}} {{x.pricingValue}}</td><td>{{x.active?'Aktív':'Inaktív'}}</td><td><button class="secondary" @click="edit(x)">Szerkesztés</button> <button class="secondary" @click="toggle(x)">{{x.active?'Letiltás':'Aktiválás'}}</button></td></tr></tbody></table></section></template>
